"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { InlineEdit, InlineEditEditor, InlineEditError, InlineEditInput, InlineEditPreview } from "@/components/ui/inline-edit";
import { useScreenFrame } from "./screen-frame-state";
import { cn } from "@/lib/utils";

/** The label row above the preview, like a frame's name on a canvas: name, then status at the right edge. */
export const ScreenFrameHeader = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function ScreenFrameHeader({ className, ...props }, ref) {
  return <div ref={ref} className={cn("flex min-h-7 min-w-0 items-center gap-1.5", className)} {...props} />;
});

/**
 * The screen's name. A click selects the screen; double click or F2 renames it in place
 * (Inline Edit's ghost variant without its underline: the frame below already frames it).
 * Enter or leaving saves, Escape cancels.
 */
export const ScreenFrameName = forwardRef<HTMLDivElement, { className?: string }>(function ScreenFrameName({ className }, ref) {
  const frame = useScreenFrame();
  const text = cn("text-xs font-medium text-muted-foreground group-data-selected/frame:text-foreground", className);
  if (!frame.onRename)
    return (
      <div ref={ref} id={frame.nameId} className={cn("min-w-0 flex-1 truncate px-1", text)}>
        {frame.name}
      </div>
    );
  return (
    <InlineEdit
      ref={ref}
      label={frame.messages.nameLabel}
      value={frame.name}
      onSave={frame.onRename}
      validate={frame.validate}
      editing={frame.renaming}
      onEditingChange={frame.setRenaming}
      disabled={frame.disabled}
      motion={frame.animated}
      variant="ghost"
      className="min-w-0 flex-1"
    >
      <InlineEditPreview
        id={frame.nameId}
        className={cn("h-7 min-h-7 w-full truncate after:hidden", text)}
        // One click selects the screen, as on a canvas; renaming takes a double click or F2.
        onClick={(event) => {
          event.preventDefault();
          frame.select({ additive: event.metaKey || event.ctrlKey, range: event.shiftKey });
        }}
        onDoubleClick={() => frame.setRenaming(true)}
        onKeyDown={(event) => {
          if (event.key !== "F2") return;
          event.preventDefault();
          frame.setRenaming(true);
        }}
      />
      <InlineEditEditor className="after:hidden">
        <InlineEditInput className={cn("h-7 text-xs font-medium", className)} />
      </InlineEditEditor>
      <InlineEditError className="px-1 text-xs" />
    </InlineEdit>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { useScreenFrame } from "./screen-frame-state";
import { cn } from "@/lib/utils";

export type ScreenFramePreviewState = "ready" | "loading" | "error";

type PreviewProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  /** The screen's thumbnail, such as an image the host renders. */
  children?: ReactNode;
  /** Shows a placeholder while the thumbnail loads, or a message when it cannot. */
  state?: ScreenFramePreviewState;
  /** Width divided by height. Defaults to a phone screen. */
  aspectRatio?: number;
};

/**
 * The screen's preview, which is also the selection target: click, Enter or Space selects
 * (holding Cmd/Ctrl or Shift is reported to the host), and F2 starts renaming.
 */
export const ScreenFramePreview = forwardRef<HTMLButtonElement, PreviewProps>(function ScreenFramePreview(
  { children, state = "ready", aspectRatio = 9 / 19.5, className, style, onClick, onKeyDown, ...props },
  ref,
) {
  const frame = useScreenFrame();
  return (
    <button
      ref={ref}
      type="button"
      aria-label={frame.messages.select(frame.name)}
      aria-pressed={frame.selected}
      aria-busy={state === "loading" || undefined}
      disabled={frame.disabled}
      data-state={state}
      className={cn(
        // Square corners by default, like a frame on a canvas; round them with className.
        "relative block w-full overflow-hidden rounded-none border border-border bg-muted text-left outline-none focus-visible:border-ring",
        // The selected ring sits outside the border so the thumbnail is not covered.
        "group-data-selected/frame:border-primary group-data-selected/frame:ring-2 group-data-selected/frame:ring-primary/25",
        frame.animated && "transition-[border-color,box-shadow] duration-150 motion-reduce:transition-none",
        className,
      )}
      style={{ aspectRatio, ...style }}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) frame.select({ additive: event.metaKey || event.ctrlKey, range: event.shiftKey });
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || event.key !== "F2" || !frame.canRename) return;
        event.preventDefault();
        frame.setRenaming(true);
      }}
      {...props}
    >
      {state === "ready" && <span className="absolute inset-0 [&>img]:size-full [&>img]:object-cover [&>img]:object-top">{children}</span>}
      {state === "loading" && (
        <span className="absolute inset-0 animate-pulse bg-foreground/5 motion-reduce:animate-none">
          <span className="sr-only">{frame.messages.loading}</span>
        </span>
      )}
      {state === "error" && (
        <span className="absolute inset-0 grid place-content-center justify-items-center gap-2 p-3 text-center text-xs text-muted-foreground">
          <svg aria-hidden viewBox="0 0 24 24" className="size-5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <rect x="3.5" y="4.5" width="17" height="15" rx="2.5" />
            <path d="m3.5 15 4.5-4.5 4 4 2.5-2.5 6 6M15 9.5h.01" />
          </svg>
          {frame.messages.error}
        </span>
      )}
    </button>
  );
});

"use client";

import { forwardRef, useId, useState } from "react";
import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { type ScreenFrameContextValue, type ScreenFrameProps, ScreenFrameContext, defaultMessages } from "./screen-frame-state";
import { cn } from "@/lib/utils";

/**
 * One app screen on a design canvas: a name label above the screen's preview, like a frame on a
 * canvas, with a status and actions. The host owns the name, selection and persistence.
 */
export const ScreenFrame = forwardRef<HTMLDivElement, ScreenFrameProps>(function ScreenFrame(
  {
    name,
    onRename,
    validate,
    selected = false,
    onSelect,
    actions,
    disabled = false,
    motion = true,
    container,
    messages: messagesProp,
    className,
    children,
    ...props
  },
  ref,
) {
  const [renaming, setRenaming] = useState(false);
  const nameId = useId();
  const messages = { ...defaultMessages, ...messagesProp };
  const canRename = !!onRename && !disabled;
  const hasMenu = canRename || !!actions;

  const context: ScreenFrameContextValue = {
    name,
    selected,
    disabled,
    animated: motion,
    renaming,
    canRename,
    nameId,
    messages,
    container,
    onRename,
    validate,
    setRenaming: (next) => setRenaming(next && canRename),
    select: (details) => !disabled && onSelect?.(details),
  };

  const frame = (
    <div
      ref={ref}
      role="group"
      aria-labelledby={nameId}
      data-selected={selected || undefined}
      data-disabled={disabled || undefined}
      data-renaming={renaming || undefined}
      className={cn("group/frame grid w-full min-w-0 content-start gap-1.5 data-disabled:opacity-60", className)}
      {...props}
    >
      {children}
    </div>
  );

  return (
    <ScreenFrameContext.Provider value={context}>
      {hasMenu ? (
        // Renaming takes the keyboard and pointer, so the menu stays closed meanwhile.
        <ContextMenu disabled={disabled || renaming} motion={motion}>
          <ContextMenuTarget className="min-w-0">{frame}</ContextMenuTarget>
          <ContextMenuContent container={container}>
            {canRename && <ContextMenuItem onClick={() => setRenaming(true)}>{messages.rename}</ContextMenuItem>}
            {actions}
          </ContextMenuContent>
        </ContextMenu>
      ) : (
        frame
      )}
    </ScreenFrameContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, createContext, useContext } from "react";

/** How a selection click should combine with the host's current selection. */
export type ScreenFrameSelectDetails = {
  /** Cmd or Ctrl was held: add or remove this screen, keeping the rest. */
  additive: boolean;
  /** Shift was held: extend the selection to this screen. */
  range: boolean;
};

/** Replaceable text for names and actions. Functions receive the screen's name. */
export type ScreenFrameMessages = {
  nameLabel: string;
  select: (name: string) => string;
  rename: string;
  loading: string;
  error: string;
};

export const defaultMessages: ScreenFrameMessages = {
  nameLabel: "Screen name",
  select: (name) => `Select ${name}`,
  rename: "Rename",
  loading: "Loading preview",
  error: "Preview unavailable",
};

export type ScreenFrameProps = Omit<ComponentPropsWithoutRef<"div">, "onSelect"> & {
  /** The screen's committed name. The application owns it. */
  name: string;
  /** Persist a new name. Enables rename by double click, F2 or the menu; return a promise to show pending. */
  onRename?: (name: string) => void | Promise<unknown>;
  /** Return a message to reject a new name. */
  validate?: (name: string) => string | null | undefined;
  /** Whether the host currently has this screen selected. */
  selected?: boolean;
  /** Called on click, Enter or Space with the modifier keys held, so the host decides the selection. */
  onSelect?: (details: ScreenFrameSelectDetails) => void;
  /** Extra menu items (Context Menu items), shown after Rename. The menu opens on right click, long press, the menu key or Shift+F10. */
  actions?: ReactNode;
  disabled?: boolean;
  /** Selection, menu and rename transitions. Reduced motion is always honored. */
  motion?: boolean;
  /** Where the menu and status tooltips are portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  messages?: Partial<ScreenFrameMessages>;
};

export type ScreenFrameContextValue = {
  name: string;
  selected: boolean;
  disabled: boolean;
  animated: boolean;
  renaming: boolean;
  canRename: boolean;
  nameId: string;
  messages: ScreenFrameMessages;
  container?: HTMLElement | null;
  onRename?: (name: string) => void | Promise<unknown>;
  validate?: (name: string) => string | null | undefined;
  setRenaming: (renaming: boolean) => void;
  select: (details: ScreenFrameSelectDetails) => void;
};

export const ScreenFrameContext = createContext<ScreenFrameContextValue | null>(null);

/** State of the nearest ScreenFrame, for building custom parts. */
export function useScreenFrame() {
  const context = useContext(ScreenFrameContext);
  if (!context) throw new Error("ScreenFrame parts must be rendered inside <ScreenFrame>.");
  return context;
}

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { useScreenFrame } from "./screen-frame-state";
import { cn } from "@/lib/utils";

export type ScreenFrameTone = "neutral" | "info" | "success" | "warning" | "danger";

const toneColor: Record<ScreenFrameTone, string> = {
  neutral: "text-muted-foreground",
  info: "text-sky-600 dark:text-sky-400",
  success: "text-emerald-600 dark:text-emerald-400",
  warning: "text-amber-600 dark:text-amber-400",
  danger: "text-destructive",
};

/** One icon per tone; pass children to use your own. */
const toneIcon: Record<ScreenFrameTone, ReactNode> = {
  neutral: <circle cx="8" cy="8" r="5.5" strokeDasharray="2.2 2.2" />,
  info: (
    <>
      <circle cx="8" cy="8" r="5.5" />
      <path d="M8 5.25V8l1.75 1.25" />
    </>
  ),
  success: (
    <>
      <circle cx="8" cy="8" r="5.5" />
      <path d="m5.75 8.1 1.5 1.5 3-3.1" />
    </>
  ),
  warning: (
    <>
      <path d="M8 2.75 13.75 13H2.25Z" />
      <path d="M8 6.75v2.5M8 11.25h.01" />
    </>
  ),
  danger: (
    <>
      <circle cx="8" cy="8" r="5.5" />
      <path d="m6.25 6.25 3.5 3.5m0-3.5-3.5 3.5" />
    </>
  ),
};

type StatusProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  /** The status's full name, such as "In review". Shown in a tooltip on hover and read by screen readers. */
  label: string;
  tone?: ScreenFrameTone;
  /** Always shown. By default the status appears while the frame is hovered or focused (and when selected on touch screens). */
  persistent?: boolean;
  /** Replace the tone's icon. */
  children?: ReactNode;
  /** Class for the tooltip. */
  tooltipClassName?: string;
};

/** A status icon at the right edge of the header. Its name shows in a tooltip on hover. */
export const ScreenFrameStatus = forwardRef<HTMLSpanElement, StatusProps>(function ScreenFrameStatus(
  { label, tone = "neutral", persistent = false, children, className, tooltipClassName, ...props },
  ref,
) {
  const frame = useScreenFrame();
  return (
    <Tooltip.Root>
      <Tooltip.Trigger
        render={
          <span
            ref={ref}
            role="img"
            aria-label={label}
            data-tone={tone}
            data-persistent={persistent || undefined}
            className={cn(
              "ml-auto inline-flex size-6 shrink-0 items-center justify-center",
              toneColor[tone],
              !persistent &&
                "opacity-0 group-hover/frame:opacity-100 group-focus-within/frame:opacity-100 pointer-coarse:group-data-selected/frame:opacity-100",
              frame.animated && "transition-opacity duration-150 motion-reduce:transition-none",
              className,
            )}
            {...props}
          />
        }
      >
        {children ?? (
          <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            {toneIcon[tone]}
          </svg>
        )}
      </Tooltip.Trigger>
      <Tooltip.Portal container={frame.container ?? undefined}>
        <Tooltip.Positioner side="top" sideOffset={6} className="z-50">
          <Tooltip.Popup
            className={cn(
              "rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background shadow-md",
              frame.animated &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
              tooltipClassName,
            )}
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
});

"use client";

export { type ScreenFrameProps, type ScreenFrameMessages, type ScreenFrameSelectDetails, useScreenFrame } from "./screen-frame-state";
export { ScreenFrame } from "./screen-frame-root";
export { ScreenFrameHeader, ScreenFrameName } from "./screen-frame-header";
export { ScreenFrameStatus, type ScreenFrameTone } from "./screen-frame-status";
export { ScreenFramePreview, type ScreenFramePreviewState } from "./screen-frame-preview";
